import React, { useState, useEffect } from 'react';
import menuItemService from '../../services/menuItemService';
import restaurantService from '../../services/restaurantService';
import { useAuth } from '../../hooks/useAuth';
import { useNavigate } from 'react-router-dom';

const AddMenuItem = () => {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [price, setPrice] = useState('');
  const [category, setCategory] = useState('');
  const [isAvailable, setIsAvailable] = useState(true);
  const [restaurantId, setRestaurantId] = useState('');
  const [loadingRestaurant, setLoadingRestaurant] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const { token } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchRestaurant = async () => {
      setLoadingRestaurant(true);
      setError('');
      try {
        const restaurantData = await restaurantService.getRestaurantByOwner(token);
        if (restaurantData) {
          setRestaurantId(restaurantData._id);
        } else {
          setError('Restaurant not found. Please create a restaurant first.');
          // Optionally redirect
        }
      } catch (err) {
        setError(err.message || 'Failed to fetch restaurant details.');
      } finally {
        setLoadingRestaurant(false);
      }
    };

    fetchRestaurant();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setSaving(true);
    setError('');
    try {
      const newMenuItem = {
        restaurantId,
        name,
        description,
        price: parseFloat(price),
        category,
        isAvailable,
      };
      await menuItemService.addMenuItem(newMenuItem, token);
      console.log('Menu item added successfully.');
      setSaving(false);
      navigate('/restaurant/dashboard'); // Redirect to dashboard
    } catch (err) {
      setError(err.message || 'Failed to add menu item.');
      setSaving(false);
    }
  };

  if (loadingRestaurant) {
    return <div>Loading restaurant details...</div>;
  }

  if (error) {
    return <div style={{ color: 'red' }}>{error}</div>;
  }

  return (
    <div>
      <h2>Add New Menu Item</h2>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="name">Name:</label>
          <input type="text" id="name" value={name} onChange={(e) => setName(e.target.value)} required />
        </div>
        <div>
          <label htmlFor="description">Description:</label>
          <textarea id="description" value={description} onChange={(e) => setDescription(e.target.value)} />
        </div>
        <div>
          <label htmlFor="price">Price:</label>
          <input type="number" id="price" value={price} onChange={(e) => setPrice(e.target.value)} required />
        </div>
        <div>
          <label htmlFor="category">Category:</label>
          <input type="text" id="category" value={category} onChange={(e) => setCategory(e.target.value)} />
        </div>
        <div>
          <label htmlFor="isAvailable">Available:</label>
          <input
            type="checkbox"
            id="isAvailable"
            checked={isAvailable}
            onChange={(e) => setIsAvailable(e.target.checked)}
          />
        </div>
        <button type="submit" disabled={saving}>
          {saving ? 'Saving...' : 'Add Menu Item'}
        </button>
      </form>
    </div>
  );
};

export default AddMenuItem;
